def read_authority_anchor(anchor: str) -> bytes:
    '''Return exact sealed bytes for one logical Structural R0 anchor.'''
    if type(anchor) is not str:
        raise KeyError(anchor)
    try:
        return _ANCHOR_BYTES[anchor]
    except KeyError:
        raise KeyError(anchor) from None
